import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 9
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    nonblank = [
        i for i, record in enumerate(records)
        if any(cell.strip() for cell in record)
    ]
    if not nonblank:
        return {"columns": [], "rows": []}

    number = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?")

    def is_label(cell):
        text = cell.strip()
        return any(char.isalpha() for char in text) and not number.fullmatch(text)

    def looks_like_data(record):
        values = [cell.strip() for cell in record if cell.strip()]
        return bool(values) and all(number.fullmatch(value) for value in values)

    header_index = None
    first_full_width = None
    first_label_row = None
    for position, index in enumerate(nonblank):
        record = records[index]
        if len(record) != expected_width:
            continue
        if first_full_width is None:
            first_full_width = index
        if not all(is_label(cell) for cell in record):
            continue
        if first_label_row is None:
            first_label_row = index
        if position + 1 < len(nonblank):
            if looks_like_data(records[nonblank[position + 1]]):
                header_index = index
                break

    if header_index is None:
        header_index = first_label_row
    if header_index is None:
        header_index = first_full_width
    if header_index is None:
        header_index = nonblank[0]

    columns = records[header_index][:]
    data = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, data), default=0))

    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    return {
        "columns": columns,
        "rows": [record + [""] * (width - len(record)) for record in data],
    }
